import{_ as o,o as a,c as i,a2 as t}from"./chunks/framework.CC9cRD7J.js";const n="/Staff-wiki/guide-inventory-shield.svg",h=JSON.parse('{"title":"Blindaje Anti-Exploit de Inventario","description":"","frontmatter":{},"headers":[],"relativePath":"modo-staff/bloqueo-inventario.md","filePath":"modo-staff/bloqueo-inventario.md","lastUpdated":1793576062000}'),r={name:"modo-staff/bloqueo-inventario.md"};function d(s,e,l,c,u,m){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="blindaje-anti-exploit-de-inventario" tabindex="-1">Blindaje Anti-Exploit de Inventario <a class="header-anchor" href="#blindaje-anti-exploit-de-inventario" aria-label="Permalink to &quot;Blindaje Anti-Exploit de Inventario&quot;">​</a></h1><p><img src="'+n+'" alt="Esquema de Blindaje Anti-Exploits"></p><p>En muchas versiones antiguas de plugins de moderación, los moderadores podían accidentalmente (o intencionadamente) transferir objetos de su modo staff a otros jugadores, cofres o soportes de armaduras. En <strong>StaffPlus 5.0.4</strong>, se ha implementado un sistema estricto de <strong>bloqueo inamovible (Hardware Inventory Lock)</strong>.</p><hr><h2 id="🔒-mecanismos-de-proteccion-activos" tabindex="-1">🔒 Mecanismos de Protección Activos <a class="header-anchor" href="#🔒-mecanismos-de-proteccion-activos" aria-label="Permalink to &quot;🔒 Mecanismos de Protección Activos&quot;">​</a></h2><h3 id="_1-bloqueo-de-movimiento-en-hotbar-e-inventario" tabindex="-1">1. Bloqueo de Movimiento en Hotbar e Inventario <a class="header-anchor" href="#_1-bloqueo-de-movimiento-en-hotbar-e-inventario" aria-label="Permalink to &quot;1. Bloqueo de Movimiento en Hotbar e Inventario&quot;">​</a></h3><ul><li>Queda anulado cualquier intento de arrastrar (<code>InventoryDragEvent</code>), hacer clic normal o usar atajos con los números <code>1</code> al <code>9</code> (<code>NUMBER_KEY</code>).</li><li>El moderador no puede reorganizar los objetos de moderación ni cambiarlos de casilla.</li></ul><h3 id="_2-bloqueo-en-modo-creativo-inventorycreativeevent" tabindex="-1">2. Bloqueo en Modo Creativo (<code>InventoryCreativeEvent</code>) <a class="header-anchor" href="#_2-bloqueo-en-modo-creativo-inventorycreativeevent" aria-label="Permalink to &quot;2. Bloqueo en Modo Creativo (`InventoryCreativeEvent`)&quot;">​</a></h3><ul><li>Aunque el modo staff asigne el modo de juego creativo para facilitar el vuelo y la patrulla, los moderadores tienen <strong>restringido retirar objetos del catálogo de creativo</strong> hacia su barra de accesos o hacia el mundo exterior.</li></ul><h3 id="_3-prohibicion-de-dropeo-y-tecla-offhand-f" tabindex="-1">3. Prohibición de Dropeo y Tecla Offhand (<code>F</code>) <a class="header-anchor" href="#_3-prohibicion-de-dropeo-y-tecla-offhand-f" aria-label="Permalink to &quot;3. Prohibición de Dropeo y Tecla Offhand (`F`)&quot;">​</a></h3><ul><li>La tecla de soltar ítems (<code>Q</code>) está interceptada y cancelada en <code>PlayerDropItemEvent</code>.</li><li>La tecla de cambio de mano secundaria (<code>F</code>) está interceptada en <code>PlayerSwapHandItemsEvent</code>. Los gadgets permanecen siempre fijos en la mano principal.</li></ul><h3 id="_4-proteccion-contra-soportes-de-armadura-y-entidades" tabindex="-1">4. Protección contra Soportes de Armadura y Entidades <a class="header-anchor" href="#_4-proteccion-contra-soportes-de-armadura-y-entidades" aria-label="Permalink to &quot;4. Protección contra Soportes de Armadura y Entidades&quot;">​</a></h3><ul><li>Interceptado en <code>PlayerArmorStandManipulateEvent</code>: es imposible equipar las herramientas de staff a soportes de armadura.</li><li>Interceptado en <code>PlayerInteractEntityEvent</code>: se impide colocar ítems en marcos invisibles o comerciar con aldeanos mientras se está en servicio.</li></ul><h3 id="_5-recogida-de-suelo-deshabilitada-entitypickupitemevent" tabindex="-1">5. Recogida de Suelo Deshabilitada (<code>EntityPickupItemEvent</code>) <a class="header-anchor" href="#_5-recogida-de-suelo-deshabilitada-entitypickupitemevent" aria-label="Permalink to &quot;5. Recogida de Suelo Deshabilitada (`EntityPickupItemEvent`)&quot;">​</a></h3><ul><li>Mientras un moderador esté en Modo Staff o con Vanish activado, no absorberá ningún objeto caído del suelo, evitando limpiar accidentalmente zonas de muerte o botines de jugadores.</li></ul><hr><h2 id="📦-cofres-silenciosos-silent-chests" tabindex="-1">📦 Cofres Silenciosos (Silent Chests) <a class="header-anchor" href="#📦-cofres-silenciosos-silent-chests" aria-label="Permalink to &quot;📦 Cofres Silenciosos (Silent Chests)&quot;">​</a></h2><p>Cuando un moderador en Modo Staff abre un cofre o contenedor:</p><ul><li>No se reproduce la animación de apertura para los jugadores cercanos.</li><li>No se emite el sonido de cofre.</li><li>El staff ve una vista virtual protegida: no se pueden ingresar objetos de staff dentro del cofre.</li></ul>',19)])])}const v=o(r,[["render",d]]);export{h as __pageData,v as default};
